export type WasmExports = {
  ping: () => string
  parse_frontmatter: (content: string) => string
}

/**
 * Load and instantiate the parser-native WASM module from raw bytes.
 * Uses the wasm-pack generated init function from the pkg/ directory.
 *
 * The pkg/ directory is generated by `wasm-pack build --target web --out-dir pkg`.
 * It must exist before this function is called at runtime.
 */
export async function loadWasm(wasmBytes: BufferSource): Promise<WasmExports> {
  // Dynamically import the wasm-pack generated glue module.
  // The init function accepts a BufferSource and returns the exports.
  // @ts-ignore — pkg/ is generated by wasm-pack build and may not exist at type-check time
  const glue = await import("../pkg/parser_native.js") as {
    default: (input?: BufferSource) => Promise<void>
    ping: () => string
    parse_frontmatter: (content: string) => string
  }
  await glue.default(wasmBytes)
  return {
    ping: glue.ping,
    parse_frontmatter: glue.parse_frontmatter,
  }
}
